//! Unsigned constructor/call XDR generated by the production TypeScript compiler.
//! No RPC, network account, signed envelope or customer key is used by this host.
use deposit_trigger::DepositTrigger;
use paiflow_splitter::Splitter;
use payer::Payer;
use soroban_sdk::{
    testutils::{Ledger as _, MockAuthInvoke},
    token,
    xdr::{self, FromXdr},
    Address, Bytes, Env, IntoVal, String, Symbol, TryFromVal, Val, Vec,
};
#[path = "../../../payment-test-token.rs"]
mod payment_test_token;

fn value<T: TryFromVal<Env, Val>>(env: &Env, values: &Vec<Val>, index: u32) -> T {
    T::try_from_val(env, &values.get(index).unwrap())
        .ok()
        .unwrap()
}
fn hex(value: &str) -> std::vec::Vec<u8> {
    let bytes = value.trim().as_bytes();
    assert_eq!(bytes.len() % 2, 0);
    bytes
        .chunks_exact(2)
        .map(|pair| {
            let digit = |byte: u8| match byte {
                b'0'..=b'9' => byte - b'0',
                b'a'..=b'f' => byte - b'a' + 10,
                _ => panic!("fixture hex"),
            };
            digit(pair[0]) * 16 + digit(pair[1])
        })
        .collect()
}

fn run_fixture(path: &std::path::Path, wasm: bool, expect_resource_refusal: bool) {
    let env = Env::default();
    env.cost_estimate().budget().reset_unlimited(); // Fixture construction is not deployment profiling.
    env.ledger().set_sequence_number(10);
    env.mock_all_auths(); // Construction and synthetic token minting only.
    let bytes = hex(&std::fs::read_to_string(path).unwrap());
    let packet = Vec::<Val>::from_xdr(&env, &Bytes::from_slice(&env, &bytes)).unwrap();
    let asset: Address = value(&env, &packet, 1);
    let nodes: Vec<Val> = value(&env, &packet, 2);
    let calls: Vec<Val> = value(&env, &packet, 3);
    env.register_at(&asset, payment_test_token::WideToken, ());
    let token = payment_test_token::WideTokenClient::new(&env, &asset);
    let mut contracts = std::vec::Vec::<Address>::new();
    for index in (0..nodes.len()).rev() {
        let node: Vec<Val> = value(&env, &nodes, index);
        let address: Address = value(&env, &node, 1);
        let kind: String = value(&env, &node, 2);
        let args: Vec<Val> = value(&env, &node, 3);
        let filename = if kind == String::from_str(&env, "DEPOSIT_TRIGGER") {
            if !wasm {
                env.register_at(&address, DepositTrigger, args.clone());
            }
            "deposit_trigger"
        } else if kind == String::from_str(&env, "SPLITTER") {
            if !wasm {
                env.register_at(&address, Splitter, args.clone());
            }
            "paiflow_splitter"
        } else {
            assert_eq!(kind, String::from_str(&env, "PAYER"));
            if !wasm {
                env.register_at(&address, Payer, args.clone());
            }
            "payer"
        };
        if wasm {
            let bytes = std::fs::read(format!(
                "../../target/wasm32v1-none/release/{filename}.wasm"
            ))
            .unwrap();
            env.register_at(&address, bytes.as_slice(), args);
        }
        token.mint(&address, &99); // Unsolicited funds must never subsidize a call.
        contracts.push(address);
    }
    let root_node: Vec<Val> = value(&env, &nodes, 0);
    let root: Address = value(&env, &root_node, 1);
    let mut wallets = std::vec::Vec::<Address>::new();
    let mut payers = std::vec::Vec::<Address>::new();
    for call in calls.iter() {
        let call = Vec::<Val>::try_from_val(&env, &call).unwrap();
        let args: Vec<Val> = value(&env, &call, 2);
        let payer: Address = value(&env, &args, 0);
        if !payers.contains(&payer) {
            token.mint(&payer, &100_000);
            payers.push(payer.clone());
        }
        if !wallets.contains(&payer) {
            wallets.push(payer);
        }
        let payouts: Vec<Val> = value(&env, &call, 3);
        for payout in payouts.iter() {
            let payout = Vec::<Val>::try_from_val(&env, &payout).unwrap();
            let address: Address = value(&env, &payout, 0);
            if !wallets.contains(&address) {
                wallets.push(address);
            }
        }
    }
    // The SDK's debug auth observer exhausts a separate shadow budget on guest
    // calls. Observation is disabled for bounded WASM diagnostics ONLY, while
    // actual exact source-account credentials remain enforced by the host.
    if wasm {
        env.host().set_invocation_hook(None).unwrap();
    }
    for call in calls.iter() {
        let call = Vec::<Val>::try_from_val(&env, &call).unwrap();
        let name: String = value(&env, &call, 0);
        let mut succeeds: bool = value(&env, &call, 1);
        let args: Vec<Val> = value(&env, &call, 2);
        let payer: Address = value(&env, &args, 0);
        let amount: i128 = value(&env, &args, 2);
        let payouts: Vec<Val> = value(&env, &call, 3);
        let before: std::vec::Vec<i128> =
            wallets.iter().map(|wallet| token.balance(wallet)).collect();
        let transfer: Vec<Val> = (&payer, &root, amount).into_val(&env);
        let xdr::ScAddress::Account(account) = xdr::ScAddress::from(&payer) else {
            panic!("payer account")
        };
        env.host().set_source_account(account).unwrap();
        env.set_auths(&[xdr::SorobanAuthorizationEntry {
            credentials: xdr::SorobanCredentials::SourceAccount,
            root_invocation: (&MockAuthInvoke {
                contract: &root,
                fn_name: "execute_v1",
                args: args.clone(),
                sub_invokes: &[MockAuthInvoke {
                    contract: &asset,
                    fn_name: "transfer",
                    args: transfer,
                    sub_invokes: &[],
                }],
            })
                .into(),
        }]);
        if wasm {
            if expect_resource_refusal {
                // Captured network CPU/RAM ceilings, still using this SDK's local
                // cost model and invocation metering. This is not RPC simulation.
                env.cost_estimate()
                    .budget()
                    .reset_limits(400_000_000, 41_943_040);
            } else {
                env.cost_estimate().budget().reset_default();
            }
        } else {
            // Keep full auth observation in the native functional run. SDK v26's
            // debug auth snapshots exceed their separate shadow budget at the
            // 20-recipient boundary. The identical guest run below retains the
            // default execution budget with only observation disabled.
            env.cost_estimate().budget().reset_unlimited();
        }
        let attempt = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            env.try_invoke_contract::<(), soroban_sdk::Error>(
                &root,
                &Symbol::new(&env, "execute_v1"),
                args,
            )
        }));
        if expect_resource_refusal {
            let panic = attempt
                .expect_err("the structural ceiling is not an executable resource guarantee");
            let message = panic
                .downcast_ref::<std::string::String>()
                .map(std::string::String::as_str)
                .or_else(|| panic.downcast_ref::<&str>().copied())
                .unwrap_or("unexpected panic type");
            assert!(
                message.contains("Error(Budget, ExceededLimit)"),
                "unrelated failure: {message}"
            );
            std::println!("40-node/20-recipient resource refusal: {} instructions, {} budget memory bytes; verifying rollback", env.cost_estimate().budget().cpu_instruction_cost(), env.cost_estimate().budget().memory_bytes_cost());
            env.cost_estimate().budget().reset_unlimited();
            succeeds = false;
        } else {
            let result = attempt.unwrap();
            assert_eq!(result.is_ok(), succeeds, "{name:?}: {result:?}");
        }
        if succeeds && !wasm {
            assert_eq!(env.auths()[0].0, payer);
        }
        if wasm && succeeds {
            let resources = env.cost_estimate().resources();
            assert!(resources.instructions < 100_000_000);
            assert!(resources.mem_bytes < 40_000_000);
            std::println!(
                "{} {name:?}: {} instructions, {} metered memory bytes (bounded local diagnostic)",
                path.file_stem().unwrap().to_string_lossy(),
                resources.instructions,
                resources.mem_bytes
            );
        }
        for (index, wallet) in wallets.iter().enumerate() {
            let mut delta = if succeeds && wallet == &payer {
                -amount
            } else {
                0
            };
            for payout in payouts.iter() {
                let payout = Vec::<Val>::try_from_val(&env, &payout).unwrap();
                let recipient: Address = value(&env, &payout, 0);
                if succeeds && wallet == &recipient {
                    delta += value::<i128>(&env, &payout, 1);
                }
            }
            assert_eq!(
                token.balance(wallet),
                before[index] + delta,
                "{name:?} recipient {wallet:?}"
            );
        }
        for address in &contracts {
            assert_eq!(
                token::Client::new(&env, &asset).balance(address),
                99,
                "{name:?}: unrelated funds"
            );
        }
    }
}
fn fixtures(wasm: bool) {
    let directory = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/fixtures/execution-acceptance");
    let mut paths: std::vec::Vec<_> = std::fs::read_dir(directory)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension == "xdr-hex")
                && !path
                    .file_stem()
                    .unwrap()
                    .to_string_lossy()
                    .starts_with("structural-")
        })
        .collect();
    paths.sort();
    assert_eq!(
        paths.len(),
        3,
        "all three representative business cases must run"
    );
    for path in paths {
        run_fixture(&path, wasm, false);
    }
}
#[test]
fn production_xdr_reuses_deployments_without_changing_constants_or_other_payments() {
    fixtures(false);
}
#[test]
#[ignore = "requires local reviewed release WASMs; no network or funded wallets"]
fn production_xdr_executes_against_reviewed_wasms() {
    fixtures(true);
}

#[test]
#[ignore = "manual structural-ceiling resource probe; requires reviewed local WASMs"]
fn probe_structural_ceiling() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/fixtures/execution-acceptance/structural-ceiling-40-nodes-20-recipients.xdr-hex");
    run_fixture(&path, true, true);
}
